parameters.jsCode:
const body = $json.body || $json;
const payment = body.data || body;

return {
  json: {
    event: body.event || 'PAYMENT_SUCCESS',
    paymentId: payment.id || payment.razorpayPaymentId || 'PAY-0000',
    amount: payment.amount || payment.amountPaid || '0',
    label: payment.label || payment.description || 'Website Milestone Payment',
    clientName: payment.clientName || payment.client?.name || 'Client',
    clientEmail: payment.clientEmail || payment.client?.email || 'N/A',
    clientPhone: payment.clientPhone || payment.client?.phone || 'N/A',
    paidAt: new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })
  }
};

parameters.jsonBody:
={
  "messaging_product": "whatsapp",
  "to": "{{ $json.clientPhone }}",
  "type": "text",
  "text": {
    "body": "💰 *dev.hyd Payment Confirmed* 💰\n\nHi {{ $json.clientName }}, we received your payment of ₹{{ $json.amount }} for *{{ $json.label }}*. Thank you!"
  }
}
